add(parameter_id="ge030-constructor-evidencias-calidad", category="Gestión de calidad", element="Constructor", parameter="Evidencias de cumplimiento", classification="condicion_normativa", value=text_value("Debe entregar evidencias de cumplimiento de códigos, reglamentos y normas, junto con pruebas, ensayos, análisis e investigaciones previstas."), standard="GE.030", numeral="Artículo 9", conditions=["Las evidencias deben relacionarse con los elementos y procesos ejecutados."], warning="Fotografías generales no sustituyen certificados, protocolos y resultados identificados.", faq_category="Compra de Materiales y Control de Calidad", question="¿Qué evidencias de calidad debe conservar y entregar el constructor?", answer="Resultados de pruebas y ensayos, análisis, investigaciones de campo y documentos que demuestren cumplimiento de normas y proyecto.")
add(parameter_id="ge030-supervisor-exige-calidad", category="Gestión de calidad", element="Supervisor de obra", parameter="Responsabilidad de calidad", classification="condicion_normativa", value=text_value("El supervisor debe exigir la aplicación de la gestión de calidad y requerir aclaraciones sobre aspectos ambiguos o no definidos."), standard="GE.030", numeral="Artículo 10", conditions=["Su actuación debe ser preventiva y orientada a alcance, plazo, calidad y costo."], warning="Autorizar verbalmente una modificación ambigua sin consulta deja la obra sin trazabilidad.", faq_category="Licencias, Planos y Responsables", question="¿Qué debe hacer el supervisor cuando un plano es ambiguo o incompleto?", answer="Debe requerir las aclaraciones o consultas necesarias y exigir la gestión de calidad de forma preventiva.")
